import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.1lnE8eph.js";const h=JSON.parse('{"title":"Specification: Reusable Module Resizing Package","description":"","frontmatter":{},"headers":[],"relativePath":"specs/009-reusable-module-resizing-package.md","filePath":"specs/009-reusable-module-resizing-package.md"}'),r={name:"specs/009-reusable-module-resizing-package.md"};function o(l,e,c,s,d,p){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="specification-reusable-module-resizing-package" tabindex="-1">Specification: Reusable Module Resizing Package <a class="header-anchor" href="#specification-reusable-module-resizing-package" aria-label="Permalink to &quot;Specification: Reusable Module Resizing Package&quot;">​</a></h1><h2 id="scope-and-precedence" tabindex="-1">Scope and precedence <a class="header-anchor" href="#scope-and-precedence" aria-label="Permalink to &quot;Scope and precedence&quot;">​</a></h2><p>Historical. The public hook, divider component, and separately imported stylesheet in RP-01 were replaced by a single <code>ResizableSplit</code> component that imports its own CSS; see the <a href="./../packages/module-resizing/README">module resizing package README</a>.</p><p>Extract the current hybrid two-pane Grid resizing interaction into a reusable, packable React package while preserving the behavior specified in <a href="./008-hybrid-grid-module-resizing">Hybrid Grid Module Resizing</a>. The existing application remains a consumer, not a second implementation. Historical Flexbox requirements remain documented separately.</p><h2 id="package-contract" tabindex="-1">Package contract <a class="header-anchor" href="#package-contract" aria-label="Permalink to &quot;Package contract&quot;">​</a></h2><ul><li>RP-01: Provide <code>@busmap/module-resizing</code> under <code>packages/module-resizing</code>, with a public React hook, native divider component, distributable CSS, and type declarations.</li><li>RP-02: Package output shall be installable from an offline-transferred tarball and shall not depend on the application, editor, Baseplate, Redux, or a third-party splitter. React shall be a peer dependency.</li><li>RP-03: Build and pack shall include runtime JavaScript, declarations, stylesheet, and integration documentation. Do not bundle React.</li><li>RP-03a: Implement the package in strict TypeScript and generate public declarations from the checked implementation during build and prepack.</li><li>RP-04: The hook shall accept enabled state, committed percentage, configured limits, and a host-owned commit callback. Invalid enabled values shall fail explicitly.</li><li>RP-05: Export panel ref/style and separator ref/event/ARIA props; the divider shall render a native focusable separator when supplied those props and an accessible label.</li><li>RP-06: The host shall supply exactly two direct panes and an appropriately sized container. Fixed divider width is 12px; breakpoint is below 840px.</li><li>RP-07: Preserve frame-coalesced previews, no movement-time state commits, cached measurement, pointer capture, RTL, limits, touch target, keyboard, ARIA, cleanup, and mobile behavior in specification 008.</li><li>RP-08: Scope styles to package classes; support destination design tokens with fallbacks. Avoid changing unrelated panel/editor styling.</li><li>RP-09: Keep persistence behind the callback: the existing Redux preferences package and editor continue to own committed values and backend behavior.</li><li>RP-10: Preserve recursive layout, module placement, UUID paths, editor drop handlers, non-resizable panels, and preference synchronization.</li></ul><h2 id="integration-documentation" tabindex="-1">Integration documentation <a class="header-anchor" href="#integration-documentation" aria-label="Permalink to &quot;Integration documentation&quot;">​</a></h2><ul><li>RP-11: Document install/pack, React peer, CSS import, typed/public API, layout JSON, module assignment, hook wiring, initialization, editor DnD, preferences adapter, air-gapped limitations, validation, and cleanup.</li><li>RP-12: Explicitly distinguish the standalone tarball from the separate Redux preference DataSource and its own dependencies.</li><li>RP-13: Explain that <code>onChange</code> must update committed state and explicitly handle persistence errors; the resizing package does not provide storage.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ol><li>A clean workspace builds the package before the application build/dev.</li><li>Package test exercises actual extracted interaction code at the app boundary.</li><li>A packed tarball includes JS, CSS, declarations, and README and excludes React and source-workspace dependencies.</li><li>A TypeScript consumer resolves the tarball exports, stylesheet, and React peer; invalid option types fail the consumer typecheck.</li><li>Existing resizing regressions, preference tests, typecheck, and app build pass.</li><li>Browser verifies desktop/mobile dragging, RTL, touch, cleanup, editor properties, and non-resizable panels without changed behavior.</li><li>Existing editor DnD is preserved; movement does not update generic layout state or dispatch preference updates until completion.</li><li>Integration guide gives complete starterkit and air-gapped steps, including the required separate preference adapter and known limitations.</li></ol><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-goals&quot;">​</a></h2><p>No automatic 60fps guarantee, multi-pane splitting, Redux bundling, publishing to an external registry, new Web Components, server implementation, or framework other than React.</p>',12)])])}const m=a(r,[["render",o]]);export{h as __pageData,m as default};
